@Injectable()
class Counter {
  n = 0
}
const a = app.get(Counter)
const b = app.get(Counter)
a.n = 1
console.log(b.n)

@Controller()
class HelloController {
  @Get()
  ping() {
    return 2
  }
}
console.log(app.get(HelloController).ping())

@Injectable()
class Num {
  value() {
    return 3
  }
}
@Injectable()
class Box {
  constructor(private num: Num) {}
  read() {
    return this.num.value()
  }
}
console.log(app.get(Box).read())

@Injectable()
class Sum {
  add(a: number, b: number) {
    return a + b
  }
}
@Controller()
class SumController {
  constructor(private sum: Sum) {}
  @Get()
  run() {
    return this.sum.add(2, 3)
  }
}
console.log(app.get(SumController).run())

const n = await new ParseIntPipe().transform('4', {
  type: 'param',
  data: 'id',
})
console.log(n)

try {
  await new ParseIntPipe().transform('x', {
    type: 'query',
    data: 'n',
  })
} catch (e) {
  console.log(e.getStatus())
}

const p = new DefaultValuePipe(5)
console.log(p.transform(undefined, { type: 'query' }))
console.log(p.transform(8, { type: 'query' }))

class TimesPipe {
  constructor(private n: number) {}
  transform(value: number) {
    return value * this.n
  }
}
console.log(new TimesPipe(3).transform(2))

@Injectable()
class Hidden {
  n = 7
}
@Module({ providers: [Hidden], exports: [Hidden] })
class A {}
@Module({ imports: [A] })
class B {}
console.log(app.get(Hidden).n)

@Injectable()
class Hidden {}
@Injectable()
class Consumer {
  constructor(public h: Hidden) {}
}
@Module({ providers: [Hidden] })
class A {}
@Module({ imports: [A], providers: [Consumer] })
class B {}
try {
  await Test.createTestingModule({ imports: [B] }).compile()
  console.log(1)
} catch {
  console.log(0)
}

@Controller()
class DoneController {
  @HttpCode(204)
  done() {
    return 9
  }
}
console.log(new DoneController().done())

class Missing {}
@Injectable()
class Box {
  constructor(@Optional() private missing?: Missing) {}
  flag() {
    return this.missing ? 1 : 0
  }
}
console.log(app.get(Box).flag())

@Injectable()
class A {
  n = 1
}
@Injectable()
class B {
  n = 2
}
@Injectable()
class C {
  constructor(private a: A, private b: B) {}
  out() {
    return this.a.n + this.b.n
  }
}
console.log(app.get(C).out())

console.log(
  await new ParseFloatPipe().transform('1.5', {
    type: 'query',
    data: 'n',
  }),
)
